# application-dev.properties
server.port=9090
app.welcome.message=DEV: Hello, welcome to my application

// DemoController
@Value("${app.welcome.message}") private String message;
@Value("${app.welcome.code}") private Integer code;

@GetMapping("/greet")
public ResponseEntity<String> greet() {
    return ResponseEntity.ok(message + " : " + code);
}

@Service
@Profile({"dev", "default", "staging"})
public class DummyNotificationServiceImpl implements NotificationService {
    public String send() { return "Here is a dummy notification"; }
}

@Service
@Profile("prod")
public class NotificationServiceImpl implements NotificationService {
    public String send() { return "Here is a notification"; }
}

